import {totals,shiftMonth,validMonth,euro,monthName} from './planner.js';
import {themeColor} from './theme.js';

export function planChanges(state,month){
 const previous=shiftMonth(month,-1);if(!validMonth(previous))return null;
 const now=totals(state,month),before=totals(state,previous),groups=new Map();
 for(const [items,sign] of [[now.items,1],[before.items,-1]])for(const i of items){
  const key=i.groupId||i.id,entry=groups.get(key)||{id:i.id,title:i.title,type:i.type,change:0};
  entry.change+=sign*i.monthlyAmount*(i.type==='income'?1:-1);groups.set(key,entry);
 }
 return {previous,delta:now.remaining-before.remaining,before:before.remaining,now:now.remaining,changes:[...groups.values()].filter(x=>x.change).sort((a,b)=>Math.abs(b.change)-Math.abs(a.change))};
}
export function renderPlanChanges(state,month,esc){const c=planChanges(state,month);if(!c||!c.changes.length)return '';return `<details class="plan-explanation"><summary><span>${c.delta?euro(Math.abs(c.delta))+(c.delta>0?' mehr':' weniger')+' frei als im Vormonat':'Gleicher Spielraum, andere Verteilung'}</span><small>Warum?</small></summary><p class="helper">Vergleich der Monatspläne mit ${monthName(c.previous)}. Tatsächlich erfasste Käufe werden hier nicht verglichen.</p><div class="change-list">${c.changes.map(x=>`<button data-action="change-detail" data-id="${x.id}" data-month="${month}"><span>${esc(x.title)}</span><strong class="${x.change<0?'negative':'positive'}">${x.change>0?'+':'−'}${euro(Math.abs(x.change))}</strong></button>`).join('')}</div><p class="helper">Plus erhöht Deinen Spielraum, Minus senkt ihn. Quartals- und Jahreszahlungen zählen im jeweiligen Zahlungsmonat.</p></details>`;}

export function renderCategorySpending(r,esc,mode='spent',filter=''){
 const cats=[...r.categories].filter(c=>c[mode]>0).sort((a,b)=>b[mode]-a[mode]),total=cats.reduce((n,c)=>n+c[mode],0);let offset=0;
 return `<section class="spending-composition"><div class="section-head"><h2>Wohin Dein Geld geht</h2><div class="tiny-tabs"><button data-action="spending-mode" data-id="spent" aria-pressed="${mode==='spent'}" class="${mode==='spent'?'active':''}">Erfasst</button><button data-action="spending-mode" data-id="planned" aria-pressed="${mode==='planned'}" class="${mode==='planned'?'active':''}">Geplant</button></div></div><div class="spending-chart-layout"><div class="spending-ring"><svg viewBox="0 0 200 200" role="group" aria-label="Ausgaben nach Kategorie"><circle cx="100" cy="100" r="78" fill="none" stroke="var(--line)" stroke-width="22"/>${cats.map(c=>{const share=c[mode]/total*100,gap=cats.length>1?Math.min(.8,share*.1):0,html=`<circle class="interactive-arc" role="button" tabindex="0" data-action="spending-category" data-id="${c.id}" aria-label="${esc(c.name)}: ${euro(c[mode])}" cx="100" cy="100" r="78" fill="none" stroke="${themeColor(c.color)}" stroke-width="${c.id===filter?28:22}" pathLength="100" stroke-dasharray="${share-gap} ${100-share+gap}" stroke-dashoffset="${-offset}" transform="rotate(-90 100 100)"/>`;offset+=share;return html;}).join('')}</svg><div><strong>${euro(total)}</strong><span>${mode==='spent'?'als Ausgabe erfasst':'Ausgaben geplant'}</span></div></div><div class="spending-category-list">${cats.map(c=>`<button data-action="spending-category" data-id="${c.id}" class="${filter===c.id?'selected':''}" aria-pressed="${filter===c.id}"><i style="background:${themeColor(c.color)}"></i><span>${esc(c.name)}<small>${Math.round(c[mode]/total*100)} %</small></span><b>${euro(c[mode])}</b></button>`).join('')||'<p class="helper">Die Verteilung erscheint mit Deinem ersten Eintrag.</p>'}</div></div><p class="helper">Kategorie antippen, um die passenden Planposten und Zahlungen zu sehen. Sparraten sind keine Konsumausgaben.</p></section>`;
}
